<style>
.guest-workspace{max-width:820px;margin:20px auto 100px;padding:0 16px;color:#172b4d}
.guest-panel{background:white;border:1px solid #e3e8ef;border-radius:16px;padding:22px;margin-bottom:18px;box-shadow:0 6px 20px #10284008}
.guest-panel h1,.guest-panel h2{margin-top:0;font-size:22px}.guest-panel p{line-height:1.6}
.guest-panel label{display:block;font-weight:600;margin:16px 0 6px}.guest-panel input,.guest-panel select,.guest-panel textarea{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;padding:12px;border-radius:8px;font:inherit;background:white;color:#172b4d}
.guest-button{display:inline-block;border:0;border-radius:8px;background:#0b2f6b;color:white;padding:13px 20px;text-decoration:none;font:inherit;cursor:pointer;margin-top:16px}.guest-button:disabled{opacity:.6}
.guest-table{width:100%;border-collapse:collapse;font-size:14px}.guest-table th,.guest-table td{padding:12px 8px;border-bottom:1px solid #e3e8ef;text-align:left;vertical-align:top}
.guest-muted{color:#667085;font-size:13px}.guest-alert{padding:14px;border-radius:8px;background:#edf4ff;margin-bottom:14px}.guest-error{color:#a02121}
</style>
